"""Frozen foundational obligations for Earth and Environmental Sciences.

The rows name the complete Layer-One question surface before external source
identities or outcomes are opened. They do not import conventional Earth-system
models, empirical constants or earlier SFT answers as derivational premises.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class EarthEnvironmentObligation:
    claim_id: str
    title: str
    family: str
    carrier: str
    relation: str
    retained_record: str
    evidence_boundary: str
    statement: str
    falsification_condition: str


FAMILY_ORDER = (
    "earth_system_observation",
    "planetary_budgets",
    "geological_material_history",
    "interior_geodynamics",
    "seismic_volcanic",
    "hydrosphere_cryosphere",
    "atmosphere_weather",
    "ocean_coast",
    "climate_system",
    "biogeochemical_ecological",
    "environmental_transport_quality",
    "evidence_hazard_handoffs",
)


def row(
    suffix: str,
    title: str,
    family: str,
    carrier: str,
    relation: str,
    retained_record: str,
    evidence_boundary: str,
    statement: str,
    falsification_condition: str,
) -> EarthEnvironmentObligation:
    return EarthEnvironmentObligation(
        "SFT-EARTH-" + suffix + "-001",
        title,
        family,
        carrier,
        relation,
        retained_record,
        evidence_boundary,
        statement,
        falsification_condition,
    )


