def validate_inventory() -> None:
    if len(EARTH_ENVIRONMENT_OBLIGATIONS) != 74:
        raise ValueError("Earth foundational question decomposition must contain its 74 explicit rows")
    if len({item.claim_id for item in EARTH_ENVIRONMENT_OBLIGATIONS}) != len(EARTH_ENVIRONMENT_OBLIGATIONS):
        raise ValueError("Earth inventory contains duplicate claim identities")
    observed = tuple(dict.fromkeys(item.family for item in EARTH_ENVIRONMENT_OBLIGATIONS))
    if observed != FAMILY_ORDER:
        raise ValueError("Earth inventory is not in declared dependency order")
    for item in EARTH_ENVIRONMENT_OBLIGATIONS:
        if not all((item.title.strip(), item.carrier.strip(), item.relation.strip(), item.retained_record.strip(), item.evidence_boundary.strip(), item.statement.strip(), item.falsification_condition.strip())):
            raise ValueError(f"Earth obligation has an empty field: {item.claim_id}")


validate_inventory()


